    ["чили"]="Чили",
    ["швейцария"]="Швейцария",
    ["швеция"]="Швеция",
    ["шотландия"]="Шотландия",
    ["шри-ланка"]="Шри-Ланка",
    ["эквадор"]="Эквадор",
    ["экваториальная гвинея"]="Экваториальная Гвинея",
    ["эритрея"]="Эритрея",
    ["эсватини"]="Эсватини",
    ["эстония"]="Эстония",
    ["эфиопия"]="Эфиопия",
    ["юар"]="ЮАР",
    ["югославия"]="Югославия",
    ["южная корея"]="Республика Корея",
    ["южная осетия"]="Южная Осетия",
    ["южно-африканская республика"]="ЮАР",
    ["южный вьетнам"]="Южный Вьетнам",
    ["южный йемен"]="Южный Йемен",
